def solve(g):
    h=len(g); w=len(g[0])
    out=[]
    for r in range(0,h,2):
        row=[]
        for c in range(0,w,2):
            block=[g[rr][cc] for rr in range(r,min(r+2,h)) for cc in range(c,min(c+2,w))]
            row.append(max(block))
        out.append(row)
    return out
