def compress(g):
    rows=[g[0]]
    for r in g[1:]:
        if r!=rows[-1]: rows.append(r)
    # then columns
    out=[list(x) for x in zip(*rows)]
    cols=[out[0]]
    for c in out[1:]:
        if c!=cols[-1]: cols.append(c)
    return [list(x) for x in zip(*cols)]
